// JFLT Vocabulary Database — Balanced answer + length distribution
// Generated by scripts/balance-vocab-grammar.mjs

export const VOCAB = {
  1: [
    { question: "A soldier is told to 'stand by'. What does this mean?", options: ["Be ready and wait", "Go to sleep", "Leave the area", "Report to the commander"], answer: 0, ex: "【意味】待機する／そのまま待て。 'Stand by' = be ready and wait. Opposite: 'stand down' = return to normal readiness." },
    { question: "What does 'FOB' stand for?", options: ["Forward Operations Brief", "Forward Operating Base", "First Officer Battalion", "Field Operations Battalion"], answer: 1, ex: "【意味】前進作戦基地（FOB）。 FOB = Forward Operating Base — a secured forward military position used to support tactical operations." },
    { question: "What is a 'sitrep'?", options: ["Site preparation", "Signal transmission", "Situation report", "Security threat report"], answer: 2, ex: "【意味】状況報告（SITREP）。 SITREP = Situation Report — a regular update on the current operational situation." },
    { question: "In NATO radio procedure, what does 'Roger' mean?", options: ["I disagree according to standard doctrine", "Please repeat", "Send the message again", "Message received and understood"], answer: 3, ex: "【意味】了解・受信完了。 'Roger' = received and understood. 'Wilco' = I will comply. 'Say again' = repeat. 'Out' = end of transmission." },
    { question: "What is a 'checkpoint'?", options: ["A place where vehicles or people are stopped and inspected", "A list of tasks to complete", "A medical examination in the conventional sense of the term", "A secure communications room"], answer: 0, ex: "【意味】検問所。 A checkpoint is a designated location where soldiers stop and verify identity and documentation." },
    { question: "What does 'personnel' mean?", options: ["Personal items belonging to soldiers", "The people working in an organisation", "Written orders in standard military usage", "A type of military rank"], answer: 1, ex: "【意味】要員・人員。 'Personnel' = the people of an organisation. 'All personnel must report by 0800.'" },
    { question: "What is a 'briefing'?", options: ["A short written report", "A type of military uniform", "A formal meeting to give information", "A secret mission under normal operational conditions"], answer: 2, ex: "【意味】説明会・ブリーフィング。 A briefing is a meeting where key information is presented before a mission or activity." },
    { question: "What does 'deploy' mean in military context?", options: ["To destroy equipment", "To retreat from a position", "To sign a treaty as commonly understood in the field", "To send forces to a specific location"], answer: 3, ex: "【意味】展開する・派遣する。 'Deploy' = to move troops or equipment into position for action. 'NATO deployed 3,000 troops to the eastern flank.'" },
    { question: "What is the 'mess hall'?", options: ["Where soldiers eat their meals", "A messy area on the base", "Storage for damaged equipment", "Punishment area according to standard doctrine"], answer: 0, ex: "【意味】食堂。 Mess hall (or 'mess') = the dining facility on a military base." },
    { question: "What does 'casualty' mean?", options: ["An accident in the conventional sense of the term", "A person injured or killed", "A vehicle breakdown", "A communication failure"], answer: 1, ex: "【意味】死傷者。 Casualty = a person injured, killed, or otherwise unable to continue duty due to operations." },
    { question: "What is 'MEDEVAC' short for?", options: ["Medical Evaluation", "Medication Vacation", "Medical Evacuation", "Medical Variation"], answer: 2, ex: "【意味】医療後送（メドエバック）。 MEDEVAC = Medical Evacuation — transport of injured personnel to medical facilities, often by helicopter." },
    { question: "What does 'chain of command' refer to?", options: ["A type of radio equipment", "A logistics supply chain", "A communication chain under normal operational conditions", "The hierarchy of officers from junior to senior"], answer: 3, ex: "【意味】指揮系統。 Chain of command = the line of authority from junior to senior officers in a military unit." },
    { question: "What does 'in transit' mean?", options: ["Moving from one place to another", "Stopped for repairs", "On guard duty", "Off duty as commonly understood in the field"], answer: 0, ex: "【意味】移動中・輸送中。 'In transit' = currently moving between locations. 'The convoy is in transit to the FOB.'" },
    { question: "What is an 'objective' in military context?", options: ["A type of weapon according to standard doctrine", "A goal to be achieved", "A defensive position", "A piece of equipment"], answer: 1, ex: "【意味】任務目標。 Objective = a goal or aim of a military operation. 'The objective is to secure the bridge.'" },
    { question: "What does 'mandatory' mean?", options: ["Optional in the conventional sense of the term", "Recommended", "Required by rules", "Forbidden"], answer: 2, ex: "【意味】必須の・義務的な。 'Mandatory' = required, must be done. 'Attendance at the briefing is mandatory.'" },
    { question: "What does 'AWOL' stand for?", options: ["Available When On Liberty", "Awaiting Withdrawal Of Leave", "Acting Without Official License", "Absent Without Leave"], answer: 3, ex: "【意味】無断離隊（AWOL）。 AWOL = Absent Without Leave — military personnel absent from duty without permission, but not intending to desert." },
    { question: "What is an 'NCO'?", options: ["A non-commissioned officer such as a sergeant or corporal", "A junior soldier still in basic training under normal operational conditions", "An officer commissioned by the head of state", "A specialist in nuclear-related operations"], answer: 0, ex: "【意味】下士官（NCO）。 NCO = Non-Commissioned Officer — enlisted leaders (sergeants, corporals) who form the backbone of military units." },
    { question: "What does the order 'Dismissed!' mean at the end of a formation?", options: ["Stand at attention and remain in place", "You are released; you may leave", "Form ranks for inspection by the officer", "Report immediately to your supervising officer"], answer: 1, ex: "【意味】解散！。 'Dismissed' = you are released from formation and may leave. Usually given by the senior officer or NCO present." },
    { question: "What is a 'rendezvous point'?", options: ["A storage area for damaged supplies according to standard doctrine", "A medical treatment area near combat", "A pre-arranged location where units meet up", "A communications tower for radio relay"], answer: 2, ex: "【意味】集合地点・会同点（RV）。 Rendezvous (RV) = a pre-agreed meeting place. 'RV at grid four-four-niner Bravo at zero-six-hundred.'" },
    { question: "What is a 'patrol' in military operations?", options: ["A formal parade held for senior visiting officers", "A training exercise held inside the barracks in the conventional sense of the term", "A medical check carried out before deployment", "A small group sent out to monitor an area or gather information"], answer: 3, ex: "【意味】哨戒（パトロール）。 Patrol = a small unit moving through an area to observe, gather information, or maintain security." },
    { question: "What does 'ammunition' mean?", options: ["Bullets, shells, and other items fired from weapons", "Equipment used to carry weapons safely on patrol", "The training given to recruits in marksmanship", "A storage facility for military vehicles in standard military usage"], answer: 0, ex: "【意味】弾薬。 Ammunition (often shortened to 'ammo') = projectiles, cartridges, and explosives used in weapons." },
    { question: "What are 'barracks'?", options: ["Vehicles used to transport soldiers in the field", "Buildings where soldiers live on a military base", "Reinforced bunkers used for combat operations", "Storage areas for weapons and ammunition supplies"], answer: 1, ex: "【意味】兵舎。 Barracks = the buildings where military personnel are housed on base." },
    { question: "What is 'reveille' on a military base?", options: ["The evening meal for all enlisted personnel", "A weekly inspection of soldiers' equipment as commonly understood in the field", "The bugle call or signal that wakes soldiers in the morning", "A formal goodbye when soldiers leave a unit"], answer: 2, ex: "【意味】起床ラッパ。 Reveille = the morning signal (bugle, recording, or whistle) waking personnel. Counterpart of 'taps' at end of day." },
    { question: "What does 'KIA' stand for?", options: ["Known Intelligence Asset", "Key Internal Authority", "Kept In Administration", "Killed In Action"], answer: 3, ex: "【意味】戦死（Killed in Action）。 KIA = Killed In Action — personnel killed during combat operations. Related: WIA (Wounded In Action), MIA (Missing In Action)." },
    { question: "What does 'extract' mean in the order 'extract the team'?", options: ["Remove or rescue the team from an area", "Provide medical care to the team in place", "Resupply the team with food and ammunition", "Promote a member of the team to a higher rank"], answer: 0, ex: "【意味】救出・収容する。 Extract = to remove or pull out (especially from a dangerous area). 'Extraction' is the operation to bring personnel back safely." },
    { question: "What does 'POW' stand for?", options: ["Pre-Operational Warning", "Prisoner Of War", "Patrol Of Watch", "Position Of Weakness"], answer: 1, ex: "【意味】戦争捕虜（POW）。 POW = Prisoner of War — a person captured by an enemy force during armed conflict. Protected under the Geneva Conventions." },
    { question: "What does 'requisition' mean in a supply context?", options: ["A delivery confirmation for received goods", "A penalty for using too many supplies under normal operational conditions", "A formal request to obtain supplies or equipment", "A surplus item being sent back to storage"], answer: 2, ex: "【意味】支給要求・請求。 Requisition = an official request for supplies, equipment, or personnel. Soldiers 'put in a requisition' for needed items." },
    { question: "What is a 'salute' in military custom?", options: ["A type of weapon training routine", "A weekly officer meeting on the base", "A standard radio call sign as commonly understood in the field", "A formal hand gesture of respect to a superior"], answer: 3, ex: "【意味】敬礼。 Salute = a formal gesture of respect, typically a raised right hand to the brow, rendered to superiors and the national flag." },
    { question: "What does 'uniform' mean?", options: ["The official clothing worn by military personnel", "Equipment carried in the field by soldiers according to standard doctrine", "A standardized vehicle type used in convoys", "A medical injection given before deployment"], answer: 0, ex: "【意味】制服・軍服。 Uniform = the official standardised clothing worn by military personnel, identifying service, rank, and unit." },
    { question: "What does 'rank' mean in the military?", options: ["The number of soldiers within a unit", "An official level or position in the hierarchy", "A type of physical exercise routine in the conventional sense of the term", "A formal weapons inspection process"], answer: 1, ex: "【意味】階級。 Rank = official level in the military hierarchy (private, sergeant, captain, etc.), determining authority and pay." },
    { question: "What is a 'squad'?", options: ["A team for sports competitions on base in standard military usage", "An officer-level command group at headquarters", "The smallest tactical military unit, usually 8-12 soldiers", "A type of basic training course for recruits"], answer: 2, ex: "【意味】分隊。 Squad = smallest tactical unit, usually 8-12 soldiers, led by a sergeant. Several squads form a platoon." },
    { question: "What is a 'platoon'?", options: ["A formation used for marching parade practice", "A type of armored personnel vehicle under normal operational conditions", "A morning roll call held on the base", "A military unit of around 30-40 soldiers led by a lieutenant"], answer: 3, ex: "【意味】小隊。 Platoon = unit of about 30-40 soldiers (several squads), typically commanded by a lieutenant." },
    { question: "What is a 'company' in a military sense?", options: ["A military unit of around 100-200 soldiers, larger than a platoon", "A civilian business contracted by the military", "A social gathering of officers on the base", "A type of military training facility as commonly understood in the field"], answer: 0, ex: "【意味】中隊。 Company = unit of roughly 100-200 soldiers (several platoons), usually commanded by a captain." },
    { question: "What is a 'battalion'?", options: ["A small reconnaissance team operating ahead of forces", "A military unit of around 300-800 soldiers made of several companies", "A type of armored personnel carrier used in convoys", "A field hospital deployed near combat operations according to standard doctrine"], answer: 1, ex: "【意味】大隊。 Battalion = unit of 300-800 soldiers (several companies), typically commanded by a lieutenant colonel." },
    { question: "What is a 'brigade'?", options: ["A class of naval warship for coastal defence", "A military headquarters staff section", "A military unit larger than a battalion, typically 3-5 battalions", "A medical evacuation specialist unit in the conventional sense of the term"], answer: 2, ex: "【意味】旅団。 Brigade = formation of several battalions (typically 3-5), commanded by a colonel or brigadier general." },
    { question: "What does 'enlisted' mean?", options: ["Officers commissioned through a military academy programme", "Civilian contractors working alongside the military in standard military usage", "Reservists temporarily called up for short-term duty", "Non-officer military personnel who have signed up for service"], answer: 3, ex: "【意味】兵卒・下士官（非士官）。 Enlisted = non-officer personnel (privates through sergeants major). Distinct from officers, who are commissioned." },
    { question: "What is a 'recruit'?", options: ["A new soldier in initial training", "A senior officer with combat experience", "A retired veteran returning to service", "A foreign national assisting allied forces"], answer: 0, ex: "【意味】新兵。 Recruit = a newly enlisted person undergoing basic training before joining a regular unit." },
    { question: "What does 'veteran' mean?", options: ["A young person not yet enlisted in the military", "A person who has served in the armed forces, especially in war", "A senior officer commanding a permanent base as commonly understood in the field", "A military intelligence specialist in covert operations"], answer: 1, ex: "【意味】退役軍人・ベテラン。 Veteran = a person who has served in the armed forces, particularly one with combat experience or who has retired from service." },
    { question: "What does 'discharge' mean in personnel context?", options: ["To fire a weapon at the firing range according to standard doctrine", "To unload supplies from a transport vehicle", "To officially release a person from military service", "To send a written order down the chain of command"], answer: 2, ex: "【意味】除隊。 Discharge = official release from military service. Types include honourable, general, and dishonourable." },
    { question: "What does 'leave' mean in military personnel terms?", options: ["The act of deserting a post without permission", "A reassignment to a different military unit", "A formal resignation submitted to the chain of command", "Authorized time off duty granted to military personnel"], answer: 3, ex: "【意味】休暇。 Leave = authorised absence from duty (annual leave, compassionate leave, R&R). Unauthorised absence is AWOL." },
    { question: "What is 'drill' in military training?", options: ["Repetitive training in military procedures and formations", "A power tool used for digging defensive positions", "A type of formal operational order issued before missions", "A standardised interrogation technique used on detainees"], answer: 0, ex: "【意味】教練・訓練。 Drill = repetitive practice of procedures (marching, weapons handling, formations) to build discipline and automatic response." },
    { question: "What is 'boot camp'?", options: ["A camping area used for short field exercises", "The basic training course for new military recruits", "A storage facility for military boots and uniforms", "An advanced officer training school for senior leaders"], answer: 1, ex: "【意味】新兵訓練。 Boot camp = the intensive basic training course where new recruits learn fundamental military skills and discipline." },
    { question: "What is a 'dog tag'?", options: ["A formal nickname assigned to officers as commonly understood in the field", "A unit patch worn by veteran personnel only", "An identification tag worn around the neck by service members", "A radio call sign used by reconnaissance units"], answer: 2, ex: "【意味】認識票。 Dog tags = metal identification tags worn by service members, listing name, service number, blood type, and religion." },
    { question: "What does 'PT' stand for in the military?", options: ["Patrol Tactics", "Personnel Transport", "Permanent Transfer", "Physical Training"], answer: 3, ex: "【意味】体力錬成（Physical Training）。 PT = Physical Training — the daily fitness regimen for military personnel, including running, calisthenics, and strength work." },
    { question: "What is 'chow' in military slang?", options: ["Informal term for food or a meal in the military", "A type of standard-issue military boot", "A small reconnaissance vehicle used on patrol", "A radio communication code word in the conventional sense of the term"], answer: 0, ex: "【意味】食事（俗語）。 Chow = informal military slang for food. 'Chow hall' = mess hall; 'chow time' = meal time." },
    { question: "What does 'duty' mean in military service?", options: ["Personal property formally assigned to a soldier in standard military usage", "A task or period of work assigned as part of one's service", "An optional task offered to volunteers within a unit", "A formal award given for years of completed service"], answer: 1, ex: "【意味】勤務・任務。 Duty = an assigned task or responsibility. 'On duty' = currently working; 'duty roster' = list showing who is assigned to what." },
    { question: "What is a 'roster'?", options: ["A type of tactical map used during operational planning", "A formal complaint procedure for personnel grievances", "A list of personnel and their assigned duties or rotations", "A radio frequency directory used for communications under normal operational conditions"], answer: 2, ex: "【意味】勤務名簿・当番表。 Roster = a list of personnel showing duty assignments, rotations, or schedule. 'Duty roster' shows who works when." },
    { question: "What is a 'convoy'?", options: ["A type of armored personnel carrier used in cities", "A communications network linking dispersed units", "A defensive perimeter established around a base as commonly understood in the field", "A group of vehicles travelling together, often for protection"], answer: 3, ex: "【意味】車列・護送車隊。 Convoy = a group of vehicles travelling together, often with armed escort for protection through hostile areas." },
    { question: "What is a 'base' in the military sense?", options: ["A permanent installation where military forces are stationed", "A temporary forward observation post in the field according to standard doctrine", "A type of mobile command vehicle used in operations", "A radio relay tower for long-range communications"], answer: 0, ex: "【意味】基地。 Military base = a permanent installation housing military forces, equipment, and support facilities." },
    { question: "What does 'gear' mean in military usage?", options: ["A type of military rank insignia worn on uniforms", "The equipment and supplies carried or used by personnel", "A formal piece of administrative paperwork in the conventional sense of the term", "A small handheld communications device used on patrol"], answer: 1, ex: "【意味】装備・装具。 Gear = equipment and supplies (weapons, kit, body armour, pack). 'Get your gear' = collect your equipment." },
    { question: "What is a 'ration' in military supply?", options: ["A type of standard military marching formation in standard military usage", "A formal discipline procedure for minor offences", "A fixed allowance of food issued to military personnel", "A fitness assessment given to newly arrived recruits"], answer: 2, ex: "【意味】糧食・配給食。 Ration = a fixed daily allowance of food (e.g., MRE — Meal, Ready-to-Eat). Combat rations are pre-packaged for field use." },
    { question: "What does 'supply' mean as a noun in logistics?", options: ["A formal operational order for an upcoming mission", "A written report on personnel readiness levels under normal operational conditions", "A communications channel between forward units", "Materials, food, ammunition, and equipment provided to forces"], answer: 3, ex: "【意味】補給物資。 Supply = the materials, food, fuel, ammunition, and equipment provided to military forces. The 'supply chain' delivers it." }
  ],
  2: [
    { question: "What does 'Rules of Engagement (ROE)' refer to?", options: ["The formal dress code for officers under normal operational conditions", "The regulations governing when and how force may be used", "The schedule for military exercises", "The NATO ranking system in standard military usage"], answer: 1, ex: "【意味】交戦規則（ROE）。 ROE = directives defining when armed forces may initiate or continue combat. Every soldier must know the ROE for their mission." },
    { question: "What does 'OPORD' stand for?", options: ["Officer Planning Report", "Observation Post Record", "Operational Order", "Operational Ordinance"], answer: 2, ex: "【意味】作戦命令書（Operation Order）。 OPORD = Operation Order — formal document directing a military unit to conduct a specific operation." },
    { question: "What is meant by 'escalation of force'?", options: ["Increasing the number of troops in an area", "Moving to a higher alert level as commonly understood in the field", "Requesting immediate air support", "A progressive series of warnings before using lethal force"], answer: 3, ex: "【意味】武力の段階的行使。 EOF = a graduated sequence (warnings, warning shots, etc.) before resorting to lethal force. Standard procedure at checkpoints." },
    { question: "What does 'force protection' mean?", options: ["Measures to preserve the combat power of a military force", "Protecting classified documents", "Training recruits for combat according to standard doctrine", "The legal authority to use weapons"], answer: 0, ex: "【意味】部隊防護。 Force protection = all measures to safeguard personnel, equipment, and facilities from threats. A standing priority for all deployed forces." },
    { question: "What does 'collateral damage' mean?", options: ["Damage to military equipment", "Unintended harm to civilians or civilian property", "The cost of an operation in the conventional sense of the term", "Damage caused by friendly fire"], answer: 1, ex: "【意味】巻き添え損害・付随被害。 Collateral damage = unintended injury to civilians or civilian property. Minimising it is a key requirement under international humanitarian law." },
    { question: "What is 'logistics' in military operations?", options: ["Military intelligence gathering", "Aerial bombardment strategy under normal operational conditions", "The organisation of supplies, transport, and resources", "Diplomatic negotiations in standard military usage"], answer: 2, ex: "【意味】兵站・ロジスティクス。 Logistics = planning and execution of supply chains: food, ammunition, fuel, transport. Critical NATO operational concept." },
    { question: "What does 'reconnaissance' (recon) mean?", options: ["A formal recognition ceremony according to standard doctrine", "A type of weapon under normal operational conditions", "A counter-attack as commonly understood in the field", "Gathering information about enemy positions or terrain"], answer: 3, ex: "【意味】偵察。 Reconnaissance = exploring an area to gain information, especially about enemy positions or terrain features." },
    { question: "What is meant by 'imminent threat'?", options: ["A threat about to happen", "A potential future threat", "A historical threat", "A minor threat"], answer: 0, ex: "【意味】切迫した脅威。 Imminent threat = a danger that is about to occur. Often a threshold for self-defence under ROE." },
    { question: "What does 'adverse' mean?", options: ["Beneficial", "Unfavourable or harmful", "Neutral according to standard doctrine", "Unexpected"], answer: 1, ex: "【意味】不利な・好ましくない。 'Adverse' = unfavourable, harmful. 'Adverse weather conditions' = bad weather affecting operations." },
    { question: "What does 'comply' mean?", options: ["To complain in the conventional sense of the term", "To complete a task", "To obey or follow rules/orders", "To compromise"], answer: 2, ex: "【意味】順守する・従う。 'Comply' = to act in accordance with rules or orders. 'Failure to comply will result in disciplinary action.'" },
    { question: "What is a 'caveat' in NATO operations?", options: ["A type of weapon system", "A backup plan in standard military usage", "A communication code under normal operational conditions", "A national restriction on how forces may be used"], answer: 3, ex: "【意味】国別制限事項・留保。 Caveat = a restriction placed by an individual nation on how its forces may be employed in alliance operations." },
    { question: "What does 'sustainment' mean in operations?", options: ["The logistics support that keeps forces operational", "Continuing combat indefinitely", "A type of training under normal operational conditions", "A defensive position"], answer: 0, ex: "【意味】持続的支援・継続維持。 Sustainment = the provision of logistics, personnel, and services to maintain operational capability over time." },
    { question: "What does 'mitigate' mean?", options: ["To make worse", "To reduce or lessen", "To eliminate completely", "To investigate"], answer: 1, ex: "【意味】軽減する・緩和する。 'Mitigate' = to make less severe. 'Measures to mitigate civilian harm.' Frequently appears in formal military writing." },
    { question: "What does 'prerequisite' mean?", options: ["An optional consideration", "A consequence according to standard doctrine", "Something required before something else", "A recommendation"], answer: 2, ex: "【意味】前提条件。 Prerequisite = something that must exist or happen before something else. 'Air superiority is a prerequisite for joint operations.'" },
    { question: "What does 'perimeter' mean?", options: ["The interior of a base", "A central command post", "A type of patrol in the conventional sense of the term", "The outer boundary of an area"], answer: 3, ex: "【意味】外周・警戒線。 Perimeter = the outer boundary of an area or position. 'Defend the perimeter' = guard the outer edges." },
    { question: "What is an 'ambush'?", options: ["A surprise attack from a concealed position", "A planned retreat from a defensive position", "A routine patrol along a known route", "A formal request for reinforcements from headquarters"], answer: 0, ex: "【意味】待ち伏せ。 Ambush = a surprise attack from a concealed position, exploiting the element of surprise against unaware targets." },
    { question: "What does 'surveillance' mean?", options: ["A defensive structure built on the perimeter under normal operational conditions", "Continuous observation of a person, place, or activity", "A formal interrogation by intelligence officers", "Protection of classified information from leakage"], answer: 1, ex: "【意味】監視。 Surveillance = systematic, continuous observation to gather information. Can be visual, electronic, or signals-based." },
    { question: "What does 'doctrine' mean in a military context?", options: ["A single written order issued before an operation", "The geographic boundary of an operational area as commonly understood in the field", "Fundamental principles guiding how forces conduct operations", "A penalty imposed on personnel for misconduct in the field"], answer: 2, ex: "【意味】ドクトリン・教義。 Doctrine = officially sanctioned principles that guide how a military operates. NATO doctrine governs how allied forces fight together." },
    { question: "What does 'evacuation' mean?", options: ["Bringing reinforcements into a contested area", "Establishing a defensive position along the perimeter", "A standard rotation between units in the field", "The organised removal of people from a dangerous area"], answer: 3, ex: "【意味】避難・後送。 Evacuation = the process of moving people away from danger, whether civilians from a disaster zone or troops from a contested area." },
    { question: "What does 'fortify a position' mean?", options: ["To strengthen it with defences against attack", "To abandon it under hostile pressure", "To photograph it for intelligence purposes", "To report it to higher headquarters for action"], answer: 0, ex: "【意味】陣地を強化する・防御を固める。 Fortify = to strengthen with defensive structures (sandbags, trenches, barriers). 'Fortifications' = the defensive works themselves." },
    { question: "What does it mean to 'neutralize' a threat?", options: ["To classify the threat as low priority", "To render it incapable of causing harm", "To request additional resources to address it", "To officially report it to the chain of command"], answer: 1, ex: "【意味】無力化する。 Neutralize = to make ineffective or harmless. Can mean destroy, capture, or disable, depending on context and ROE." },
    { question: "What is a 'liaison officer'?", options: ["An officer responsible for legal advice on operations", "A senior officer who commands a combat unit under normal operational conditions", "An officer who coordinates communication between organisations", "An officer tasked with logistical resupply of forward units"], answer: 2, ex: "【意味】連絡幕僚・リエゾン将校。 Liaison officer = a representative who facilitates communication and cooperation between two units, services, or nations." },
    { question: "What does 'enforce' mean?", options: ["To request something formally from higher headquarters", "To delay something until further notice is given", "To explain a rule clearly to personnel under command", "To compel observance of a rule, law, or order"], answer: 3, ex: "【意味】強制する・執行する。 Enforce = to make people obey or comply. 'Enforce the rules of engagement' = ensure they are followed by all personnel." },
    { question: "What does 'provision' mean as a verb?", options: ["To supply with food, equipment, or other necessities", "To withdraw supplies from a forward position", "To inspect supplies before they are issued according to standard doctrine", "To redistribute supplies among multiple units"], answer: 0, ex: "【意味】補給する・調達する。 Provision (verb) = to supply with what is needed. 'The unit was provisioned for a two-week operation.' Noun: a supply of food." },
    { question: "What does 'detain' mean?", options: ["To officially release a person from custody", "To hold a person in custody, often temporarily", "To transport a person to a separate medical facility", "To question a person about a security incident"], answer: 1, ex: "【意味】拘束する。 Detain = to officially hold someone, restricting their freedom to leave. Different from arrest in legal status, depending on jurisdiction." },
    { question: "What is 'counterinsurgency' (COIN)?", options: ["A type of intelligence-gathering operation in standard military usage", "A formal alliance between neighbouring states", "Military and political operations to defeat an armed insurgency", "An economic policy to reduce instability in a region"], answer: 2, ex: "【意味】対反乱作戦（COIN）。 Counterinsurgency = combined military, political, economic, and civic actions to defeat insurgent movements while addressing root causes." },
    { question: "What does 'CASEVAC' stand for?", options: ["Casual Evacuation procedure", "Casualty Evaluation programme", "Casualty Avoidance manoeuvre", "Casualty Evacuation"], answer: 3, ex: "【意味】戦傷後送（Casualty Evacuation）。 CASEVAC = Casualty Evacuation — transport of casualties using non-dedicated medical platforms (vs MEDEVAC which uses dedicated medical assets)." },
    { question: "What does 'comprise' mean?", options: ["To consist of or be made up of", "To make a compromise on a position", "To compete with another military unit", "To prepare a formal report on an incident"], answer: 0, ex: "【意味】〜から成る・構成する。 'Comprise' = to consist of, be composed of. 'The battalion comprises four companies.' Often confused with 'compose'." },
    { question: "What does 'flank' mean in military operations?", options: ["The central commanding element of a unit according to standard doctrine", "The side or wing of a military formation or position", "The rear logistics support area behind the front", "The forwardmost element of an advancing force"], answer: 1, ex: "【意味】側面・ウィング。 Flank = the side of a military formation. 'Flank attack' = attack on the side; 'protect the flanks' = secure the sides." },
    { question: "What does 'take cover' mean?", options: ["To put on a uniform appropriate to the weather", "To assume command of an adjacent unit temporarily", "To take a position of protection from enemy fire", "To begin a formal record of an incident"], answer: 2, ex: "【意味】遮蔽を取る・伏せろ。 Cover = protection from enemy fire (behind walls, vehicles, terrain). 'Take cover' = get behind protection immediately." },
    { question: "What does 'intercept' mean?", options: ["To deliver a message between two units in standard military usage", "To request additional resources from headquarters", "To formally inspect equipment before operations", "To stop or catch something while it is moving toward a target"], answer: 3, ex: "【意味】迎撃する・傍受する。 Intercept = to stop or catch something in transit (aircraft, missile, message, communications) before it reaches its target." },
    { question: "What does 'infiltrate' mean?", options: ["To enter an area or organisation secretly and gradually", "To openly assault a defended position under normal operational conditions", "To withdraw quietly from a forward area", "To resupply a forward position by air drop"], answer: 0, ex: "【意味】潜入する。 Infiltrate = to enter secretly, especially past enemy lines or into an organisation. Opposite of exfiltrate." },
    { question: "What does 'exfiltrate' mean?", options: ["To break through enemy defences openly with force as commonly understood in the field", "To covertly withdraw from a hostile area, especially after a mission", "To gather supplies from local sources during operations", "To translate intercepted communications for intelligence use"], answer: 1, ex: "【意味】退出する・離脱する。 Exfiltrate = to leave a hostile area covertly, often after a clandestine mission. The 'exfil' is the planned escape route." },
    { question: "What does 'withdraw' mean in military operations?", options: ["To advance toward an enemy position", "To request air support immediately according to standard doctrine", "To pull back forces from a position or engagement", "To establish defensive fortifications in place"], answer: 2, ex: "【意味】撤退する。 Withdraw = to pull back forces from a position. Can be tactical (under pressure) or planned (orderly redeployment)." },
    { question: "What does 'reinforce' mean?", options: ["To replace tired soldiers with rested ones nearby", "To inspect equipment before a planned operation", "To withdraw from a position under enemy pressure", "To add troops or strength to an existing force"], answer: 3, ex: "【意味】増援する・強化する。 Reinforce = to strengthen by adding more troops, equipment, or material. 'Reinforcements' = additional units sent to support." },
    { question: "What does 'engagement' mean in military context?", options: ["A combat encounter between opposing forces", "A formal commitment to attend a meeting", "An administrative agreement between two units", "A type of training exercise involving live fire"], answer: 0, ex: "【意味】交戦。 Engagement = a combat encounter, typically of limited scope. 'Rules of engagement' govern when and how engagements may occur." },
    { question: "What does 'debrief' mean?", options: ["To prepare personnel for an upcoming operation", "To question personnel after a mission to gather information", "To formally promote a person to a higher rank", "To remove a person from active operations under normal operational conditions"], answer: 1, ex: "【意味】事後報告・デブリーフ。 Debrief = to question personnel after a mission to extract information and lessons learned. Opposite of brief (before)." },
    { question: "What does 'compliance' mean?", options: ["Active resistance against authority as commonly understood in the field", "A formal complaint against a superior", "The act of obeying rules, orders, or requests", "An optional course of voluntary action"], answer: 2, ex: "【意味】順守・遵守。 Compliance = the act of obeying or conforming. 'Compliance with orders' is fundamental to military discipline." },
    { question: "What does 'breach' mean as a verb in operations?", options: ["To defend a position against attack according to standard doctrine", "To request a ceasefire from the enemy", "To inspect a position for vulnerabilities", "To break through a barrier, defence, or rule"], answer: 3, ex: "【意味】突破する・違反する。 Breach = to break through (a wall, defence) or to break (a rule, agreement). 'Breaching charge' = explosive used to break a barrier." },
    { question: "What is a 'cordon' in security operations?", options: ["A line of personnel or barriers around an area to control access", "A type of radio call sign system in the conventional sense of the term", "A formal interrogation procedure for detainees", "A medical triage category at field hospitals"], answer: 0, ex: "【意味】包囲線・コードン。 Cordon = a line of soldiers or barriers around an area to control entry and exit. 'Cordon and search' is a common tactic." },
    { question: "What does 'envelop' mean in tactics?", options: ["To dig in and defend a fixed position in standard military usage", "To attack around the sides or rear of an enemy force", "To withdraw from contact with the enemy", "To resupply forward troops with ammunition"], answer: 1, ex: "【意味】包囲する。 Envelop = to attack around the flanks or rear, surrounding the enemy. 'Double envelopment' = attack on both flanks at once." },
    { question: "What does 'suppress' mean in combat?", options: ["To establish a defensive perimeter under normal operational conditions", "To negotiate a temporary ceasefire", "To reduce enemy effectiveness through accurate fire", "To gather intelligence about enemy positions"], answer: 2, ex: "【意味】制圧する。 Suppress = to reduce enemy effectiveness by forcing them to take cover. 'Suppressing fire' keeps enemy heads down while others manoeuvre." },
    { question: "What does 'covert' mean?", options: ["Open, public, and visible to all parties", "Conducted lawfully under treaty obligations", "Requiring formal high-level government approval", "Concealed, secret, or carried out in hiding"], answer: 3, ex: "【意味】隠密の。 Covert = hidden, secret. 'Covert operation' = an operation conducted secretly, often where sponsorship can be denied. Opposite: overt." },
    { question: "What does 'overt' mean?", options: ["Open, public, and not concealed", "Hidden from public knowledge by design", "Carried out only with allied partner support", "Approved by international organisations beforehand"], answer: 0, ex: "【意味】公然の・公開の。 Overt = open, public, not hidden. 'Overt action' is acknowledged publicly. Opposite of covert." },
    { question: "What does 'clandestine' mean?", options: ["Conducted openly with public knowledge in the conventional sense of the term", "Kept secret, especially for unlawful or improper purposes", "Authorized by the international community formally", "Carried out only during daylight hours"], answer: 1, ex: "【意味】秘密の・極秘の。 Clandestine = secret, hidden — emphasising that the activity itself is concealed (vs covert, where sponsorship is concealed)." },
    { question: "What does 'corroborate' mean?", options: ["To deny or contradict an account in standard military usage", "To translate from one language to another", "To confirm or support with additional evidence", "To classify information at a higher level"], answer: 2, ex: "【意味】裏付ける・確証する。 Corroborate = to confirm or support (a statement, theory) with additional evidence. Key concept in intelligence assessment." },
    { question: "What does 'allege' mean?", options: ["To prove conclusively with hard evidence", "To formally retract a previous statement", "To officially deny something in writing under normal operational conditions", "To claim something without yet proving it"], answer: 3, ex: "【意味】（未確認で）主張する。 Allege = to claim something is true without proving it. 'Alleged violations' = claimed but not yet verified violations." },
    { question: "What does 'presume' mean?", options: ["To assume something to be true without proof", "To know definitively with full certainty", "To prove using forensic evidence as commonly understood in the field", "To require official written authorisation"], answer: 0, ex: "【意味】推定する・前提とする。 Presume = to assume something is true without proof. 'Presumed dead' = assumed dead in the absence of confirming evidence." },
    { question: "What does 'authorize' mean?", options: ["To prepare a written report on an incident", "To give official permission or power for an action", "To translate orders into another language according to standard doctrine", "To request reinforcements through channels"], answer: 1, ex: "【意味】許可する・認可する。 Authorize = to give official permission. 'Authorized personnel only' = only those with permission may enter or act." },
    { question: "What does 'revoke' mean?", options: ["To extend the validity of an existing order", "To send a written reminder up the chain of command", "To officially cancel or withdraw something previously granted", "To formally renew a security clearance in the conventional sense of the term"], answer: 2, ex: "【意味】取り消す・撤回する。 Revoke = to officially cancel or withdraw (a permission, licence, clearance). 'Revoke security clearance' = remove access to classified material." },
    { question: "What does 'delegate' mean as a verb?", options: ["To accept responsibility from a superior officer", "To refuse a task assigned by higher authority in standard military usage", "To formally retire from a current command position", "To assign authority or responsibility to another person"], answer: 3, ex: "【意味】委任する。 Delegate (verb) = to assign authority or a task to a subordinate. Effective leadership requires appropriate delegation." },
    { question: "What does 'coordinate' mean in joint operations?", options: ["To organise different elements so they work together effectively", "To act independently without consulting other units under normal operational conditions", "To request additional supplies from headquarters first", "To prepare written reports after the operation ends"], answer: 0, ex: "【意味】調整する・連携する。 Coordinate = to organise different units, services, or actions so they work together. Joint operations depend on tight coordination." },
    { question: "What does 'notify' mean?", options: ["To request information from another party", "To formally inform someone of something", "To deny knowledge of an event officially", "To translate a message into another language"], answer: 1, ex: "【意味】通知する。 Notify = to formally inform. 'Notify next of kin' = inform the family (often used regarding casualties)." },
    { question: "What does 'ambassador' mean?", options: ["The highest-ranking diplomatic representative of one country in another", "A military attaché posted to a foreign embassy according to standard practice", "A junior official assigned to consular affairs under normal conditions", "A retired official sent on a one-off ceremonial visit abroad"], answer: 0, ex: "【意味】大使。 Ambassador = the highest-ranking diplomatic envoy, accredited to head a permanent diplomatic mission (embassy) in a foreign state." },
    { question: "What is an 'embassy' in diplomatic usage?", options: ["A temporary delegation sent for a single round of negotiations", "The permanent diplomatic mission of one state in another's capital", "A formal letter of credentials presented to the host state in standard practice", "A meeting room reserved for treaty signing under normal usage"], answer: 1, ex: "【意味】大使館。 Embassy = the permanent diplomatic mission a state maintains in another state's capital, headed by an ambassador." },
    { question: "What is a 'consulate'?", options: ["The principal diplomatic mission accredited to a foreign head of state", "A roving envoy carrying messages between capitals according to standard practice", "A diplomatic office handling visas and citizens' affairs in a foreign city", "A military liaison post within a foreign defence ministry under normal conditions"], answer: 2, ex: "【意味】領事館。 Consulate = a subsidiary diplomatic office, typically in a non-capital city, handling visas, passports, and protection of nationals abroad." },
    { question: "What does 'envoy' mean in diplomacy?", options: ["A senior judge presiding over arbitration of international disputes", "An advisor briefing the head of state on foreign policy in standard practice", "A foreign correspondent reporting on diplomatic events under normal conditions", "A messenger or representative sent on a specific diplomatic mission"], answer: 3, ex: "【意味】特使・使節。 Envoy = a diplomatic agent dispatched with a specific mission, often more flexible in rank than an ambassador. 'Special envoy' is common." },
    { question: "What is a 'delegation' in international meetings?", options: ["A group of representatives sent to negotiate or attend on behalf of a state", "A formal protest delivered through official channels in standard practice", "A written summary distributed after diplomatic meetings under normal conditions", "A ceremonial parade held before bilateral talks in the conventional sense"], answer: 0, ex: "【意味】代表団。 Delegation = the group of officials representing a state at a conference, negotiation, or international body." },
    { question: "What is a 'summit' in international diplomacy?", options: ["A standing committee of permanent representatives meeting weekly", "A meeting of the most senior leaders of states or organisations", "The signing ceremony for a previously negotiated treaty in standard practice", "A working-level dialogue between mid-ranking officials under normal conditions"], answer: 1, ex: "【意味】首脳会談。 Summit = a meeting of heads of state or government (e.g., G7 summit, NATO summit). Distinct from working-level talks." },
    { question: "What does 'dialogue' mean in diplomatic context?", options: ["A binding written agreement between two governments in standard practice", "A monologue delivered before the General Assembly under normal usage", "Ongoing discussions between parties to manage relations or resolve issues", "A formal protest lodged through diplomatic channels in the conventional sense"], answer: 2, ex: "【意味】対話。 Dialogue = sustained communication between parties to build understanding or address differences. 'Strategic dialogue' is a common diplomatic format." },
    { question: "What does 'cooperation' mean in international affairs?", options: ["Competition between rival states across overlapping interests", "Withholding information from another state in standard practice", "A formal treaty obligation under international law in normal usage", "Working jointly with another state toward shared goals or outcomes"], answer: 3, ex: "【意味】協力。 Cooperation = parties working together toward mutual interests. Spans economic, security, technical, and political cooperation." },
    { question: "What is an 'agreement' in diplomatic usage?", options: ["A mutual understanding or formal arrangement between parties", "A unilateral declaration of policy by one state in standard practice", "A binding court judgment in an international tribunal under normal conditions", "A confidential intelligence assessment shared between allies"], answer: 0, ex: "【意味】合意・協定。 Agreement = a mutual understanding, ranging from informal arrangements to formal treaties. 'Bilateral agreement' = between two states." },
    { question: "What does 'negotiation' mean in diplomacy?", options: ["The unilateral imposition of terms by the stronger party under normal conditions", "Discussion between parties to reach a mutually acceptable outcome", "A formal protest issued through diplomatic channels in the conventional sense", "Public arbitration before an international panel in standard practice"], answer: 1, ex: "【意味】交渉。 Negotiation = the process of discussion aimed at reaching agreement. Distinct from mediation (third-party assisted) and arbitration (binding decision)." },
    { question: "What is a 'dispute' in diplomatic terms?", options: ["An informal exchange of views during routine consultations between officials", "A formal alliance commitment under treaty obligations in standard practice", "A disagreement between parties, especially one requiring resolution", "A scheduled session of a multilateral institution under normal conditions"], answer: 2, ex: "【意味】紛争・対立。 Dispute = a disagreement, often over territory, trade, or treaty interpretation. 'Dispute settlement' is a key WTO/ICJ function." },
    { question: "What does 'diplomatic relations' between two states refer to?", options: ["Joint military exercises conducted on a regular schedule under normal conditions", "An economic free-trade arrangement between trading partners in standard practice", "Confidential intelligence-sharing arrangements between allied governments", "The formal channel of official contact between two governments"], answer: 3, ex: "【意味】外交関係。 Diplomatic relations = the formal status by which two states officially recognise and communicate with each other through accredited missions." },
    { question: "What does 'recognition' mean in international law?", options: ["Formal acceptance by one state of another's statehood or government", "An informal acknowledgement during private diplomatic talks", "The signing of a bilateral trade agreement in standard practice", "A confidential cable from one foreign ministry to another under normal conditions"], answer: 0, ex: "【意味】（国家・政府の）承認。 Recognition = formal acknowledgement by one state of another's existence as a sovereign state, or of a particular government as legitimate." },
    { question: "What are 'credentials' in diplomatic protocol?", options: ["A confidential briefing prepared for the foreign minister in standard practice", "The formal documents an ambassador presents to the host state's head", "A security clearance issued for access to classified materials under normal conditions", "An exchange of letters confirming travel arrangements in conventional usage"], answer: 1, ex: "【意味】信任状。 Credentials = the formal letters from a sending state's head, presented by an incoming ambassador to the host state's head of state." },
    { question: "What does 'protocol' mean in diplomacy?", options: ["A confidential treaty annex shared only between principal parties", "A consular convention regulating visa issuance in standard practice", "The formal rules and procedures governing diplomatic conduct and ceremony", "A regional defence arrangement coordinated by allied ministries under normal conditions"], answer: 2, ex: "【意味】儀礼・議定書。 Protocol has two senses: (1) the rules of diplomatic etiquette and precedence; (2) a formal supplementary agreement to a treaty." }
  ],
  3: [
    { question: "What is 'deterrence' in NATO strategy?", options: ["Using military force to defeat an enemy as commonly understood in the field", "Withdrawing forces to avoid conflict under normal operational conditions", "Preventing aggression by convincing an adversary the costs outweigh the benefits", "A diplomatic agreement in standard military usage"], answer: 2, ex: "【意味】抑止。 Deterrence = dissuading a potential aggressor through credible threat of unacceptable costs. Central to NATO's Article 5 commitment." },
    { question: "What does 'interoperability' mean in NATO doctrine?", options: ["The ability of NATO forces to operate in any weather", "A shared logistics system across the alliance as commonly understood in the field", "The standard rank structure under normal operational conditions", "The ability of different nations' forces and systems to work together effectively"], answer: 3, ex: "【意味】相互運用性。 Interoperability = ability of allied forces, units, and equipment to communicate, cooperate, and operate together seamlessly." },
    { question: "What is a 'mandate' in peacekeeping?", options: ["The formal authority given by the UN or another body to carry out a mission", "A military order from a superior in the conventional sense of the term", "A request for reinforcements according to standard doctrine", "A ceasefire agreement as commonly understood in the field"], answer: 0, ex: "【意味】委任権限・授権。 Mandate = formal authorisation defining the scope, purpose, and limits of an operation. Examples: UNIFIL, KFOR, ISAF." },
    { question: "What does 'asymmetric warfare' refer to?", options: ["War between two equal forces according to standard doctrine", "Conflict where a weaker party uses unconventional tactics against a stronger opponent", "Naval operations in restricted waters in the conventional sense of the term", "Simultaneous warfare in multiple countries in standard military usage"], answer: 1, ex: "【意味】非対称戦。 Asymmetric warfare = conflict with significant power imbalance, leading the weaker side to use guerrilla warfare, IEDs, cyber attacks, terrorism." },
    { question: "What is 'situational awareness' (SA)?", options: ["Knowledge of physical fitness levels", "Awareness of legal obligations in the conventional sense of the term", "Understanding what is happening in the operational environment", "Multilingual communication ability"], answer: 2, ex: "【意味】状況認識（SA）。 Situational awareness = understanding the current state of the battlespace — friendly, enemy, neutral positions, and ongoing events." },
    { question: "What does 'attribution' mean in cyber security?", options: ["Awarding credit for an action", "The scope of an attack", "The cost of an attack in standard military usage", "Identifying who is responsible for an attack"], answer: 3, ex: "【意味】攻撃元の特定。 Attribution = the process of determining who carried out a cyber attack. Often complex and time-consuming, especially for state-sponsored attacks." },
    { question: "What does 'cohesion' mean in alliance context?", options: ["The unity and togetherness of an alliance or unit", "A type of military formation", "The cost of operations", "A defensive strategy under normal operational conditions"], answer: 0, ex: "【意味】結束・団結。 Cohesion = the unity, solidarity, and shared commitment within an alliance or unit. Often targeted by adversary disinformation." },
    { question: "What does 'proportionate' mean in military response?", options: ["Larger than the original threat in the conventional sense of the term", "Appropriate to and matching the scale of the situation", "Smaller than necessary according to standard doctrine", "Decided by a vote as commonly understood in the field"], answer: 1, ex: "【意味】均衡のとれた・比例した。 Proportionate = matching in scale and intensity. 'Proportionate response' is a key principle of international humanitarian law." },
    { question: "What is a 'contingency plan'?", options: ["The main operational plan", "A budget proposal according to standard doctrine", "A backup plan for unexpected situations", "A training schedule"], answer: 2, ex: "【意味】不測事態対処計画。 Contingency plan = a plan prepared for possible but uncertain future events. 'We need contingency plans for all scenarios.'" },
    { question: "What does 'precedent' mean?", options: ["A high-ranking officer", "A future plan in the conventional sense of the term", "A type of agreement", "An earlier event used as an example or guide"], answer: 3, ex: "【意味】先例・判例。 Precedent = an earlier event or action serving as an example or guide for later situations. Important in legal and policy contexts." },
    { question: "What does 'consensus' mean in NATO decision-making?", options: ["General agreement among all members", "A majority vote", "A decision by the Secretary-General alone", "A military command"], answer: 0, ex: "【意味】コンセンサス・総意。 Consensus = general agreement among all parties. NATO operates on consensus, meaning every member must agree for major decisions." },
    { question: "What does 'invoke' mean?", options: ["To cancel something", "To formally activate or call upon something", "To investigate", "To delay under normal operational conditions"], answer: 1, ex: "【意味】発動する・援用する。 'Invoke' = to call upon (a law, principle, etc.) as authority. 'Article 5 was invoked after September 11.'" },
    { question: "What does 'ambiguity' mean?", options: ["Clear and direct meaning", "A specific type of order", "Open to multiple interpretations", "A military formation as commonly understood in the field"], answer: 2, ex: "【意味】曖昧さ。 Ambiguity = the quality of being open to multiple interpretations. 'Strategic ambiguity' is a deliberate policy in deterrence." },
    { question: "What does 'paramount' mean?", options: ["Of secondary importance", "Optional according to standard doctrine", "Outdated", "Of supreme or highest importance"], answer: 3, ex: "【意味】最重要の・至上の。 'Paramount' = above all others in importance. 'Civilian protection is paramount in our operations.'" },
    { question: "What does 'consolidate' mean in operations?", options: ["To strengthen or unify into a single position", "To divide forces", "To withdraw in the conventional sense of the term", "To celebrate"], answer: 0, ex: "【意味】強化・統合する。 Consolidate = to combine or unify; to strengthen a position. 'Consolidate gains' = secure and reinforce captured ground." },
    { question: "What does 'coercion' mean in strategic context?", options: ["A diplomatic effort to resolve a dispute peacefully", "The use of threats or force to compel an actor to do something", "A formal alliance commitment between two states in standard military usage", "A series of economic agreements between trading partners"], answer: 1, ex: "【意味】強制・強要。 Coercion = forcing an actor to change behaviour through threats or limited use of force. 'Coercive diplomacy' is a key strategic concept." },
    { question: "What does 'legitimacy' mean in international operations?", options: ["The technical capability to carry out a mission successfully", "A formal declaration of war against another state", "The quality of being recognised as lawful and rightful", "An evaluation of military performance after an operation"], answer: 2, ex: "【意味】正統性・合法性。 Legitimacy = the perception that an action or authority is lawful and justified. Critical for sustaining international and domestic support." },
    { question: "What does 'resilience' mean in NATO doctrine?", options: ["The speed at which forces can be moved into theatre", "The total firepower available to a military force as commonly understood in the field", "The willingness of forces to accept casualties in combat", "The ability to absorb shocks and recover quickly from disruption"], answer: 3, ex: "【意味】強靭性・レジリエンス。 Resilience = capacity to withstand, adapt to, and recover from shocks (cyber attacks, natural disasters, hybrid threats). A core NATO priority." },
    { question: "What does 'force posture' refer to?", options: ["The disposition, capabilities, and readiness of forces", "The physical fitness requirements for combat troops", "The morale and motivation of deployed personnel according to standard doctrine", "The dress and bearing of soldiers on formal parade"], answer: 0, ex: "【意味】戦力態勢。 Force posture = how forces are arranged geographically, what capabilities they hold, and how ready they are. 'Forward posture' = positioned near potential threats." },
    { question: "What is 'hybrid warfare'?", options: ["A type of training combining different national doctrines in the conventional sense of the term", "A blend of conventional, irregular, cyber, and information operations", "A military exercise involving multiple branches of service", "A peacetime mission to support civilian authorities at home"], answer: 1, ex: "【意味】ハイブリッド戦。 Hybrid warfare = coordinated use of conventional forces, irregular tactics, cyber, disinformation, and economic pressure to achieve objectives below the threshold of open war." },
    { question: "What does 'multilateral' mean?", options: ["Involving only one country acting alone in standard military usage", "Involving only two countries in agreement", "Involving multiple countries or parties acting together", "Involving a single international organisation alone"], answer: 2, ex: "【意味】多国間の。 Multilateral = involving multiple (usually three or more) parties. NATO is a multilateral alliance; UN operations are typically multilateral." },
    { question: "What does 'bilateral' mean in a diplomatic context?", options: ["Involving many nations at once across regions", "Involving an international organisation alone", "Involving non-state actors in negotiations", "Involving exactly two parties or countries"], answer: 3, ex: "【意味】二国間の。 Bilateral = involving two parties. 'Bilateral defence agreement' = a treaty between exactly two states. Compare: multilateral (many), unilateral (one)." },
    { question: "What does 'parity' mean in strategic balance?", options: ["Equality of capability between competing forces", "A significant advantage in numbers or capability", "A complete absence of military forces in a region", "A formal agreement to reduce armaments over time"], answer: 0, ex: "【意味】均衡・対等性。 Parity = equality, especially in military capability. 'Strategic parity' was a guiding concept during the Cold War nuclear balance." },
    { question: "What does 'unilateral' mean?", options: ["Done by two parties acting together by agreement", "Done by a single party acting on its own", "Done by many parties through an alliance", "Done by an international body on behalf of others"], answer: 1, ex: "【意味】単独の・一方的な。 Unilateral = acting alone, without partners. 'Unilateral withdrawal' = pulling out without consulting allies. Opposite of multilateral." },
    { question: "What does 'proliferation' mean in WMD context?", options: ["The destruction of existing weapons stockpiles", "The inspection of declared weapons facilities in the conventional sense of the term", "The spread of weapons to additional states or actors", "The peaceful use of nuclear technology for energy"], answer: 2, ex: "【意味】拡散。 Proliferation = the spread of weapons (especially nuclear, biological, chemical) to additional actors. 'Non-proliferation' is a major treaty regime (NPT)." },
    { question: "What is a 'coalition' in military terms?", options: ["A single nation's combined-arms force structure in standard military usage", "A permanent treaty-based military alliance like NATO", "An informal network of intelligence-sharing partners", "A temporary grouping of states cooperating for a specific operation"], answer: 3, ex: "【意味】連合・有志連合。 Coalition = an ad hoc grouping of states formed for a specific purpose, often a single operation. Differs from a formal alliance like NATO in being temporary." },
    { question: "What are 'sanctions' in international policy?", options: ["Penalties imposed to compel a change in behaviour", "Diplomatic awards given to cooperative states under normal operational conditions", "Formal military commitments to defend an ally", "Joint training agreements between armed forces"], answer: 0, ex: "【意味】制裁。 Sanctions = restrictive measures (economic, trade, financial, travel) imposed to pressure a state, entity, or individual to change behaviour." },
    { question: "What does 'de-escalate' mean in a crisis?", options: ["To match the adversary's level of force in response", "To reduce the intensity of a confrontation or conflict", "To withdraw completely from the area of conflict as commonly understood in the field", "To request reinforcements from allied partner nations"], answer: 1, ex: "【意味】緊張を緩和する。 De-escalate = to reduce tension or the intensity of a crisis. Opposite of escalate. 'De-escalation measures' are key to crisis management." },
    { question: "What does 'preemptive' mean in strategic context?", options: ["Responding only after being attacked", "Withdrawing forces from a contested area", "Acting first to prevent an anticipated attack", "Negotiating a settlement before any conflict begins"], answer: 2, ex: "【意味】先制の。 Preemptive = acting first to prevent an imminent attack. Distinct from 'preventive' (acting against a longer-term threat)." },
    { question: "What does 'retaliation' mean?", options: ["A diplomatic protest delivered through formal channels", "A defensive measure taken before an attack occurs", "An offer of negotiation made after a conflict ends", "Returning an attack or injury with similar action"], answer: 3, ex: "【意味】報復。 Retaliation = returning an attack in kind. 'Massive retaliation' was a Cold War nuclear doctrine; modern usage spans cyber, economic, military." },
    { question: "What is 'brinkmanship' in strategic theory?", options: ["Pushing dangerous events to the edge of disaster to gain advantage", "The practice of negotiating only from positions of weakness", "A method of training officers in crisis decision-making", "The doctrine of avoiding any direct confrontation with adversaries"], answer: 0, ex: "【意味】瀬戸際政策。 Brinkmanship = pushing a confrontation to the brink of disaster to force the adversary to back down. Risky — used by Dulles in Cold War." },
    { question: "What does 'containment' mean in foreign policy?", options: ["Encouraging an adversary to expand peacefully under normal operational conditions", "Preventing the expansion of an adversary's power or influence", "Maintaining strict isolation from all foreign affairs", "Withdrawing from international commitments and alliances"], answer: 1, ex: "【意味】封じ込め。 Containment = a strategy of preventing an adversary's expansion. Defined Cold War US strategy toward the Soviet Union (Kennan, 1946)." },
    { question: "What does 'appeasement' mean?", options: ["Strengthening alliances to deter aggression", "Imposing strict sanctions on an aggressor as commonly understood in the field", "Granting concessions to an aggressor to avoid conflict", "Building military capability to match a threat"], answer: 2, ex: "【意味】宥和（ゆうわ）政策。 Appeasement = granting concessions to avoid conflict. Carries a strongly negative connotation since Munich 1938 (Chamberlain → Hitler)." },
    { question: "What is 'détente' in international relations?", options: ["A formal military alliance between rival powers", "A complete severing of diplomatic relations", "A short ceasefire during ongoing operations", "A relaxation of tensions between hostile states"], answer: 3, ex: "【意味】デタント・緊張緩和。 Détente = easing of strained relations, especially between hostile states. The 1970s US-Soviet détente is the classic example." },
    { question: "What does 'rapprochement' mean?", options: ["The re-establishment of cordial relations between former rivals", "A deepening of existing hostility between two states", "A withdrawal of diplomatic representation from another country", "An aggressive escalation of an ongoing dispute in the conventional sense of the term"], answer: 0, ex: "【意味】関係改善・再接近。 Rapprochement = restoration of friendly relations between previously hostile parties. 'Sino-American rapprochement' under Nixon in 1972." },
    { question: "What does 'polarization' mean in geopolitics?", options: ["The merging of opposing sides into a single bloc in standard military usage", "The division of an arena into opposing camps with growing distance between them", "The development of multiple independent neutral states", "A reduction of differences between competing powers under normal operational conditions"], answer: 1, ex: "【意味】二極化。 Polarization = division into sharply opposed groups. 'Bipolar' (US-USSR Cold War) vs 'multipolar' (many great powers) vs 'unipolar' (one)." },
    { question: "What does 'realignment' mean in alliances?", options: ["The annual rotation of headquarters staff officers", "A standard logistics resupply procedure under normal operational conditions", "A significant shift in alliance relationships or strategic partnerships", "A formal protocol for joint training exercises"], answer: 2, ex: "【意味】再編・再構成。 Realignment = a significant shift in alliance structures. 'Strategic realignment' often follows major geopolitical shocks." },
    { question: "What does 'recalibration' mean in policy?", options: ["A formal protest lodged through diplomatic channels", "A complete reversal of a long-standing commitment as commonly understood in the field", "A routine annual review with no substantive changes", "An adjustment or reassessment of an approach or strategy"], answer: 3, ex: "【意味】再調整。 Recalibration = adjustment or fine-tuning of a policy or approach in response to new conditions or information." },
    { question: "What does 'constraint' mean in strategic context?", options: ["A limitation or restriction on what can be done", "A military capability that enhances options", "A diplomatic agreement opening new possibilities", "An incentive offered to encourage cooperation"], answer: 0, ex: "【意味】制約。 Constraint = a limitation restricting options. 'Operational constraints' might include weather, terrain, legal restrictions, or political limits." },
    { question: "What does 'leverage' mean as a noun in negotiation?", options: ["A formal complaint procedure used in disputes in the conventional sense of the term", "Influence or advantage that can be used to gain a desired outcome", "A mechanical device used for moving heavy equipment", "An expression of goodwill toward another party"], answer: 1, ex: "【意味】影響力・てこ。 Leverage = influence or advantage that can be applied to achieve an outcome. 'Economic leverage' uses trade/finance to pressure another state." },
    { question: "What does 'provisional' mean?", options: ["Permanent and not subject to any future change", "Approved at the highest level of authority", "Temporary or arranged for the present, pending a final arrangement", "Carried out without any formal approval in standard military usage"], answer: 2, ex: "【意味】暫定的な。 Provisional = temporary, pending something more permanent. 'Provisional government', 'provisional agreement' — explicitly subject to revision." },
    { question: "What does 'nominal' mean in usage like 'nominal control'?", options: ["Significant in scale and operationally meaningful", "Carefully measured and quantitatively precise", "Approved by the highest political authority", "Existing in name only, but not in real effect"], answer: 3, ex: "【意味】名目上の。 Nominal = in name only. 'Nominal control' = formal but not real control. Different from the financial sense (nominal vs real value)." },
    { question: "What does 'substantive' mean?", options: ["Being temporary or merely placeholder in nature", "Concerning procedural or formal matters only", "Having real importance, meaning, or value as commonly understood in the field", "Existing only in name without real effect"], answer: 0, ex: "【意味】実質的な。 Substantive = real, meaningful, having substance. 'Substantive talks' = talks that address real issues, not just procedure." },
    { question: "What does 'articulate' mean as a verb?", options: ["To remain silent on a sensitive matter", "To express clearly and effectively in words", "To delegate a decision to a subordinate officer", "To refuse to comment publicly on an issue"], answer: 1, ex: "【意味】明確に述べる・表現する。 Articulate (verb) = to express clearly. 'The Secretary articulated the new doctrine' = explained it clearly and coherently." },
    { question: "What does 'delineate' mean?", options: ["To deliberately obscure the boundaries of an issue", "To delay a decision until a later date", "To describe or define something precisely", "To delegate authority to a subordinate command"], answer: 2, ex: "【意味】明確に定義する・線を引く。 Delineate = to describe precisely or define the boundaries of. 'Delineate responsibilities' = clearly define who does what." },
    { question: "What does 'demarcate' mean?", options: ["To dispute the recognised boundary of an area", "To withdraw from an internationally recognised territory", "To negotiate a temporary informal ceasefire", "To set or mark the boundaries of something"], answer: 3, ex: "【意味】境界を定める。 Demarcate = to set the boundaries of. 'Demarcation line' = a boundary line, often dividing forces (e.g., 38th parallel in Korea)." },
    { question: "What does 'convene' mean?", options: ["To call together for a formal meeting or session", "To formally cancel a previously planned meeting", "To submit an issue for individual written comment", "To delay an important decision until later consultation"], answer: 0, ex: "【意味】招集する。 Convene = to call together. 'The North Atlantic Council convened in emergency session' = the council was called into formal meeting." },
    { question: "What does 'ratify' mean in treaty law?", options: ["To informally discuss the terms of a treaty as commonly understood in the field", "To give formal consent to a treaty, making it officially valid", "To withdraw from a previously signed treaty unilaterally", "To delay implementation of an agreed treaty"], answer: 1, ex: "【意味】批准する。 Ratify = to formally approve (a treaty, agreement) at the highest national level, making it binding. In the US, the Senate ratifies." },
    { question: "What does 'enshrine' mean in policy context?", options: ["To remove a protection that was previously granted", "To classify a document at a higher security level according to standard doctrine", "To preserve or protect something formally, often in law", "To delay a policy decision pending further review"], answer: 2, ex: "【意味】明記する・定着させる。 Enshrine = to preserve formally, often in law or a treaty. 'Article 5 enshrines collective defence' = makes it a formal, protected commitment." },
    { question: "What does 'promulgate' mean?", options: ["To withdraw an order quietly without announcement", "To classify information as restricted material", "To delay a decision until further notice is given", "To make widely known by formal announcement"], answer: 3, ex: "【意味】公布する。 Promulgate = to officially announce or put into effect (laws, regulations, doctrine). 'Promulgate new ROE' = formally issue new rules." },
    { question: "What is an 'accord' in international relations?", options: ["A formal agreement or treaty between parties", "A bilateral declaration of hostilities between states", "A request for international arbitration of a dispute", "An internal national policy directive on foreign affairs"], answer: 0, ex: "【意味】協定・合意。 Accord = a formal agreement, especially between states. Examples: Helsinki Accords (1975), Dayton Accords (1995), Abraham Accords (2020)." },
    { question: "What is a 'communiqué' in diplomacy?", options: ["A private intelligence assessment shared bilaterally", "An official public statement, typically following a meeting", "A confidential cable from an embassy to its capital", "A military operational order distributed within an alliance"], answer: 1, ex: "【意味】共同声明・コミュニケ。 Communiqué = an official public statement, often jointly issued after a summit or meeting. Sets out positions and outcomes for the record." },
    { question: "What is a 'dossier'?", options: ["A single classified telegram between embassies", "A draft of a proposed international treaty as commonly understood in the field", "A collection of documents about a particular person, event, or subject", "An informal verbal briefing given without notes"], answer: 2, ex: "【意味】書類一式・ドシエ。 Dossier = a file or collection of documents on a particular subject. 'Intelligence dossier' = collected file on a target person or topic." },
    { question: "What is a 'resolution' in a UN context?", options: ["A formal expression of the will of a UN organ on a specific matter", "A confidential cable circulated only among Security Council members in standard practice", "A bilateral treaty registered with the UN Secretariat under normal conditions", "A press briefing summarising the Secretary-General's position in conventional usage"], answer: 0, ex: "【意味】決議。 Resolution = a formal decision adopted by a UN organ. Security Council resolutions under Chapter VII can be legally binding; General Assembly resolutions are typically recommendatory." },
    { question: "What is the 'veto' power in the UN Security Council?", options: ["A consensus-building procedure used in committee deliberations under normal conditions", "The ability of a permanent member to block a substantive resolution", "A procedural rule requiring two-thirds support across all delegations in standard practice", "A right belonging only to states subject to current sanctions in conventional usage"], answer: 1, ex: "【意味】拒否権。 Veto = the power held by each of the five permanent members (P5: US, UK, France, Russia, China) to block any substantive Security Council resolution by a single negative vote." },
    { question: "What is a 'signatory' to a treaty?", options: ["A state that has formally ratified the treaty under its domestic procedures", "A state observing the treaty without any official participation in standard practice", "A state that has signed the treaty, indicating intent but not yet binding consent", "A state subject to the treaty's obligations through customary international law"], answer: 2, ex: "【意味】署名国。 Signatory = a state that has signed a treaty. Signature usually signals intent to ratify but doesn't itself bind the state — ratification is the formal consent." },
    { question: "What does 'accession' mean in treaty practice?", options: ["A state's withdrawal from a previously ratified treaty according to standard practice", "A formal protest registered against an existing treaty in conventional diplomatic usage", "Modification of a treaty's text after entry into force under normal practice", "A state becoming a party to an existing treaty without prior signature"], answer: 3, ex: "【意味】加盟・加入。 Accession = the act by which a state becomes a party to a treaty already negotiated and signed by others. Common route for joining multilateral conventions." },
    { question: "What does 'jurisdiction' mean in international law?", options: ["The legal authority of a state or tribunal to exercise its powers", "The geographic territory under a state's sovereignty in standard practice", "The diplomatic immunity enjoyed by accredited envoys under normal conditions", "The customary law applicable to a particular region in conventional usage"], answer: 0, ex: "【意味】管轄権。 Jurisdiction = the authority to make and enforce decisions. Can be territorial (within borders), personal (over nationals), or universal (e.g., for war crimes)." },
    { question: "What does 'sovereignty' mean in international relations?", options: ["A state's diplomatic immunity from foreign legal proceedings in standard practice", "Supreme authority of a state within its territory, free from external control", "The historical lineage of a country's ruling institutions in conventional usage", "Recognition of a government's legitimacy by other states under normal conditions"], answer: 1, ex: "【意味】主権。 Sovereignty = supreme political authority within a defined territory, including freedom from external interference. Foundational concept of the modern state system." },
    { question: "What is 'mediation' in dispute settlement?", options: ["A binding decision issued by an international tribunal under normal conditions", "A unilateral imposition of terms by the more powerful party in standard practice", "A third party assisting disputants to reach their own agreement", "A formal investigation conducted by a UN fact-finding mission in conventional usage"], answer: 2, ex: "【意味】調停。 Mediation = third-party assistance to help disputants reach a voluntary settlement. The mediator facilitates but does not impose. Distinct from arbitration (binding)." },
    { question: "How does 'arbitration' differ from mediation?", options: ["Arbitration is informal and non-binding, unlike formal mediation under normal practice", "Arbitration involves national courts, whereas mediation uses international panels", "Arbitration is always public, whereas mediation is held in private session", "Arbitration produces a binding decision by the arbitrator, not a voluntary settlement"], answer: 3, ex: "【意味】仲裁。 Arbitration = dispute settlement in which a neutral arbitrator (or panel) issues a binding decision. The Permanent Court of Arbitration is a key international venue." },
    { question: "What is a 'ceasefire' in conflict resolution?", options: ["A halt in hostilities, often as a step toward broader negotiations", "A complete termination of the legal state of war between parties under normal conditions", "A unilateral surrender by one side in standard military and diplomatic practice", "A bilateral defensive alliance preventing future conflict in conventional usage"], answer: 0, ex: "【意味】停戦。 Ceasefire = a suspension of fighting, usually short of a formal peace settlement. Can be temporary, conditional, or open-ended. Often a precursor to armistice or peace talks." },
    { question: "What does 'embargo' mean in international policy?", options: ["A diplomatic protest filed through official channels under standard practice", "An official ban on trade or commercial activity with a particular state", "A confidential intelligence assessment shared only with allies under normal conditions", "A naval blockade enforced by allied warships in the conventional military sense"], answer: 1, ex: "【意味】禁輸（措置）。 Embargo = an official prohibition on trade or specific exchanges (especially arms) with a target state. A type of economic sanction. 'Arms embargo' is the most common." },
    { question: "What does 'reciprocity' mean in diplomatic practice?", options: ["Strict adherence to the letter of a treaty by both parties under normal conditions", "The granting of unilateral concessions to encourage future cooperation", "Mutual exchange of equivalent treatment or concessions between states", "A multilateral framework binding all parties equally in standard practice"], answer: 2, ex: "【意味】相互主義・互恵。 Reciprocity = the principle of equivalent treatment between states. If one expels a diplomat, the other reciprocates. Trade tariffs often invoke reciprocity." },
    { question: "What is a 'moratorium' in international agreements?", options: ["A permanent prohibition of a specified activity by treaty under normal practice", "A scheduled review of treaty implementation between parties in standard usage", "A formal complaint procedure invoked before international tribunals", "An agreed temporary halt to a specified activity, pending future decision"], answer: 3, ex: "【意味】一時停止・モラトリアム。 Moratorium = an agreed temporary suspension of an activity. Examples: nuclear testing moratorium, debt repayment moratorium, whaling moratorium." },
    { question: "What does 'stipulate' mean in legal or treaty drafting?", options: ["To specify expressly as a required condition or term", "To withhold the relevant clause from a public version under normal practice", "To amend an existing provision through diplomatic note in standard usage", "To delegate interpretation to a future panel under conventional conditions"], answer: 0, ex: "【意味】規定する・明記する。 Stipulate = to require as part of an agreement, expressly written into the text. 'The treaty stipulates that...' = the treaty specifically requires." },
    { question: "What is a 'concession' in negotiation?", options: ["A binding obligation imposed on a single party by treaty under normal conditions", "Something given up by one party to facilitate reaching an agreement", "A scheduled break during prolonged multilateral negotiation sessions", "A reservation entered against a specific treaty provision in standard practice"], answer: 1, ex: "【意味】譲歩。 Concession = something one party gives up in negotiation, typically to help reach agreement. 'Mutual concessions' are the heart of compromise diplomacy." },
    { question: "What does 'impasse' mean in negotiations?", options: ["A breakthrough resolving the major outstanding issues under normal conditions", "A scheduled recess in multilateral talks within standard procedural practice", "A situation where no further progress can be made by either side", "A formal commitment to resume talks at a later date in conventional usage"], answer: 2, ex: "【意味】行き詰まり・暗礁。 Impasse = a deadlock; a situation in which negotiations cannot move forward. 'Talks reached an impasse over verification' = stuck on that issue." }
  ],
  4: [
    { question: "What is 'strategic ambiguity' in defence policy?", options: ["Unclear communication due to language barriers", "Concealing troop movements from allies under normal operational conditions", "Maintaining conflicting alliances in standard military usage", "Deliberate policy of not specifying exactly how a nation will respond"], answer: 3, ex: "【意味】戦略的曖昧性。 Strategic ambiguity = intentionally leaving adversaries uncertain about response options. NATO's nuclear posture employs this to complicate adversarial planning." },
    { question: "What does 'burden sharing' mean in NATO?", options: ["Distribution of defence spending and operational responsibilities among members", "Sharing classified intelligence according to standard doctrine", "A logistics supply system as commonly understood in the field", "Rotation of headquarters under normal operational conditions"], answer: 0, ex: "【意味】負担共有。 Burden sharing = how equitably members share costs and responsibilities of collective defence. The 2% of GDP target is the primary benchmark." },
    { question: "What does 'escalation dominance' mean?", options: ["Having superior numbers of troops in the conventional sense of the term", "Ability to maintain superior capability at every level of the escalation ladder", "Being the first to escalate as commonly understood in the field", "Suppressing enemy escalation according to standard doctrine"], answer: 1, ex: "【意味】エスカレーション支配。 Escalation dominance = possessing credible superior response options at every rung of the escalation ladder, deterring further escalation." },
    { question: "What does 'non-kinetic effect' mean?", options: ["The effect of weather on equipment in standard military usage", "The acoustic impact of artillery in the conventional sense of the term", "Actions influencing the enemy without direct physical force, such as cyber or information operations", "Logistics operations according to standard doctrine"], answer: 2, ex: "【意味】非運動的効果。 Non-kinetic effects = outcomes achieved without physical force: information operations, cyber attacks, economic pressure, psychological operations." },
    { question: "What does 'plausible deniability' mean?", options: ["A type of military formation", "A logistics term in the conventional sense of the term", "A type of intelligence", "Being able to deny something convincingly"], answer: 3, ex: "【意味】関与否認の余地。 Plausible deniability = the ability to deny responsibility for actions because evidence is insufficient or ambiguous. Adversaries deliberately exploit this in hybrid warfare." },
    { question: "What does 'predicated upon' mean?", options: ["Based or founded upon", "Predicted by", "Opposed to in standard military usage", "Unrelated to"], answer: 0, ex: "【意味】〜に基づいた。 'Predicated upon' = based upon, founded on. 'NATO's posture is predicated upon mutual defence.' High-register formal English." },
    { question: "What does 'inadvertent' mean?", options: ["Deliberate", "Unintentional", "Officially sanctioned", "Long-planned"], answer: 1, ex: "【意味】意図せざる・偶発的な。 'Inadvertent' = not on purpose, accidental. 'Inadvertent escalation' = unintended worsening of a crisis. Common in strategic discourse." },
    { question: "What does 'centrifugal' mean in alliance context?", options: ["Pulling things together", "A type of weapon as commonly understood in the field", "Tending to pull things apart", "Geographic centring"], answer: 2, ex: "【意味】求心力に反する・遠心の。 Centrifugal = tending to move outward from a centre, pulling apart. 'Centrifugal pressures on alliance solidarity' = forces pulling members apart." },
    { question: "What does 'salience' mean?", options: ["Salty taste", "Quietness in the conventional sense of the term", "Speed according to standard doctrine", "The quality of being prominent or important"], answer: 3, ex: "【意味】顕著性・重要性。 Salience = the quality of being especially noticeable or important. 'The debate has acquired renewed salience.'" },
    { question: "What does 'paradigmatic' mean?", options: ["Representing a typical example or model of something", "Old-fashioned under normal operational conditions", "Unimportant in standard military usage", "Temporary in the conventional sense of the term"], answer: 0, ex: "【意味】典型例となる・パラダイム的な。 Paradigmatic = serving as a typical example or model. 'A paradigmatic shift' = a fundamental change in approach or model." },
    { question: "What does 'asymmetry' mean?", options: ["Perfect balance in standard military usage", "Lack of equality or balance between two things", "A type of formation under normal operational conditions", "Symmetric arrangement"], answer: 1, ex: "【意味】非対称性。 Asymmetry = lack of equality, imbalance. 'Information asymmetries' = unequal information access between parties." },
    { question: "What does 'subordinated' mean?", options: ["Made more important", "Eliminated under normal operational conditions", "Made less important or placed under something", "Made independent"], answer: 2, ex: "【意味】従属させられた。 'Subordinated to' = made less important than, placed under the authority of. 'Operational logic is often subordinated to political considerations.'" },
    { question: "What does 'preclude' mean?", options: ["To allow as commonly understood in the field", "To encourage", "To delay", "To prevent or make impossible"], answer: 3, ex: "【意味】排除する・不可能にする。 'Preclude' = to prevent or make impossible. 'Measures to preclude adversarial exploitation.' Essential Level 4 vocabulary." },
    { question: "What does 'compromise' mean as a verb in security context?", options: ["To weaken, damage, or breach security of", "To reach a deal", "To improve in the conventional sense of the term", "To delay according to standard doctrine"], answer: 0, ex: "【意味】（機密などを）危殆化する・損なう。 'Compromise' (verb) = to weaken or breach security. 'The system has been compromised.' Different meaning from 'to reach a compromise.'" },
    { question: "What does 'commensurate' mean?", options: ["Different from", "Equal in scale or proportion", "Optional to in the conventional sense of the term", "Smaller than"], answer: 1, ex: "【意味】釣り合った・相応の。 Commensurate = corresponding in size, scale, or degree. 'A response commensurate with the threat.' Formal Level 4 vocabulary." },
    { question: "What does 'attrition' mean in a military context?", options: ["A formal change of command within a combat unit in standard military usage", "The recruitment shortfall in a peacetime force structure", "The gradual wearing down of an enemy through sustained losses", "A logistical resupply method using locally sourced goods"], answer: 2, ex: "【意味】消耗（戦）。 Attrition = gradual reduction of enemy strength through sustained losses. 'Attrition warfare' relies on inflicting unsustainable losses over time." },
    { question: "What does 'cognizant of' mean?", options: ["Unaware of or indifferent to the situation", "Opposed in principle to the situation described", "Acting in clear defiance of the situation", "Aware of and taking into account the situation"], answer: 3, ex: "【意味】〜を認識して・〜を踏まえて。 'Cognizant of' = aware of, having knowledge of. 'Commanders must be cognizant of the political dimension of operations.' Formal register." },
    { question: "What does 'extant' mean?", options: ["Currently existing or still in force", "Belonging entirely to a previous era", "Hypothetical or imagined in nature", "Officially classified as confidential material"], answer: 0, ex: "【意味】現存する・現行の。 Extant = currently existing, still in force. 'The extant treaty framework' = the agreements that are presently in effect. High-register formal English." },
    { question: "What does 'exigency' mean?", options: ["A long-term strategic planning horizon", "An urgent need or demand arising from circumstances", "A routine administrative procedure followed daily", "A relaxed peacetime security posture according to standard doctrine"], answer: 1, ex: "【意味】緊急の必要・急場。 Exigency = an urgent demand or pressing need. 'Operational exigencies may override standard procedures.' Common in formal military and policy writing." },
    { question: "What does 'obviate' mean?", options: ["To make something significantly more difficult to achieve", "To restate something in clearer and simpler language", "To remove the need for something or to prevent it", "To delay something until a later, undetermined date"], answer: 2, ex: "【意味】不要にする・回避する。 Obviate = to make unnecessary or to prevent. 'New procedures obviate the need for manual verification.' High-register formal vocabulary." },
    { question: "What does 'concomitant' mean?", options: ["Strongly opposed to or in direct conflict with", "Distantly preceding or following in sequence", "Considered separately from related matters", "Naturally accompanying or associated with"], answer: 3, ex: "【意味】付随する。 Concomitant = occurring or existing together with. 'Increased capability and the concomitant rise in operating costs.' Academic register." },
    { question: "What does 'tacit' mean?", options: ["Implied or understood without being explicitly stated", "Loudly and openly expressed in a public forum", "Forcefully imposed on an unwilling party under normal operational conditions", "Formally recorded in writing for the official record"], answer: 0, ex: "【意味】暗黙の。 Tacit = understood without being directly stated. 'Tacit approval' = approval that is implied by silence or behaviour rather than spoken." },
    { question: "What does 'nascent' mean?", options: ["Long-established and fully mature in form as commonly understood in the field", "Just coming into existence and beginning to develop", "Coming to a natural end after a long lifespan", "Existing only in theoretical or planning stages"], answer: 1, ex: "【意味】黎明期の・発生したばかりの。 Nascent = just beginning to develop, in early stages. 'Nascent capabilities' = capabilities that are emerging but not yet fully realised." },
    { question: "What does 'tantamount to' mean?", options: ["Significantly and meaningfully different from", "Distantly and only loosely related to", "Equivalent to or essentially the same as", "Officially and entirely separate from"], answer: 2, ex: "【意味】〜に等しい・〜も同然。 'Tantamount to' = equivalent in effect to. 'Such a move would be tantamount to a declaration of war.' Formal register, often legal or strategic." },
    { question: "What does 'underpin' mean?", options: ["To undermine or weaken something from below", "To restate the same point in different terms", "To classify a document at a higher security level", "To form the basis or foundation of something"], answer: 3, ex: "【意味】支える・土台となる。 Underpin = to support or form the foundation of. 'Shared values underpin the alliance.' Common in formal policy and academic writing." },
    { question: "What does 'ostensibly' mean?", options: ["Apparently or as outwardly claimed, though perhaps not really", "Definitely and beyond any reasonable doubt in standard military usage", "Secretly and without any public statement made", "Inevitably and as a matter of natural course"], answer: 0, ex: "【意味】表向きは・見かけ上。 Ostensibly = apparently, as claimed (often implying the real reason differs). 'Ostensibly a defensive exercise' = officially defensive, though perhaps not really." },
    { question: "What is a 'corollary'?", options: ["A document refuting a previous argument under normal operational conditions", "A logical consequence that follows from something", "A formal introduction to a longer treatise", "An unrelated and parallel development elsewhere"], answer: 1, ex: "【意味】必然的帰結・当然の結果。 Corollary = a proposition that follows naturally from another. 'A corollary of increased deterrence is heightened crisis stability.' Formal register." },
    { question: "What does 'accountability' mean in policy discourse?", options: ["The technical capability to monitor government activity in standard practice", "A constitutional immunity granted to senior officials under normal conditions", "A legal procedure for prosecuting financial misconduct in conventional usage", "Obligation to answer for one's actions, including acceptance of consequences"], answer: 3, ex: "【意味】説明責任。 Accountability = being answerable for one's conduct, with consequences for failure. 'Accountability gap' = where actors evade responsibility. Central to good governance discourse." },
    { question: "What does 'impunity' mean in human rights discourse?", options: ["Freedom from punishment or being held accountable for misconduct", "A formal pardon granted by a head of state under normal practice", "Diplomatic immunity enjoyed by accredited envoys in standard usage", "A statute of limitations preventing prosecution after a set period"], answer: 0, ex: "【意味】不処罰。 Impunity = the situation where wrongdoers escape consequences. 'Culture of impunity' = systemic failure to hold perpetrators (often state actors) to account." },
    { question: "What does 'fungible' mean?", options: ["Highly specialised and lacking close substitutes under normal market conditions", "Interchangeable with another item of the same kind", "Subject to specific export controls under standard international practice", "Restricted to a single authorised user in conventional usage"], answer: 1, ex: "【意味】代替可能な。 Fungible = interchangeable, where one unit is as good as another (e.g., currency, oil, kilograms of wheat). 'Fungible assistance' = aid that can be redirected internally." },
    { question: "What does 'confluence' mean in strategic analysis?", options: ["A sharp divergence between competing trends under normal conditions", "An unintended consequence of multiple separate policies in standard usage", "A coming together of factors, trends, or interests at a single point", "A historical analogy applied to current circumstances in conventional usage"], answer: 2, ex: "【意味】合流・結節点。 Confluence = a flowing together; a meeting point of multiple factors. 'A confluence of economic and demographic pressures' = these forces coinciding." },
    { question: "What does 'schism' mean in alliance discourse?", options: ["A formal restructuring of decision-making procedures under normal practice", "A scheduled review of strategic priorities in conventional alliance usage", "A renegotiation of cost-sharing arrangements between members under standard conditions", "A serious split or fundamental division within a group"], answer: 3, ex: "【意味】分裂・対立。 Schism = a deep division, especially within an alliance or institution. Originally religious; now widely used for any institutional split. 'Transatlantic schism' = US-Europe divergence." },
    { question: "What does 'ascendancy' mean in geopolitics?", options: ["A dominant position of influence or controlling power", "An ongoing decline in standing under normal historical conditions", "A formal title conferred by international convention in standard usage", "A neutral status maintained between competing powers in conventional practice"], answer: 0, ex: "【意味】優位・支配的地位。 Ascendancy = the state of being dominant or holding the upper hand. 'The ascendancy of liberal democracy after 1989' = its dominant position in that period." },
    { question: "What is 'hegemony' in international relations theory?", options: ["An equal partnership among great powers under standard balance-of-power conditions", "Dominance of one state over others within a particular system", "A multilateral institution coordinating great-power consultation in conventional usage", "A formal alliance commitment to collective defence under normal treaty practice"], answer: 1, ex: "【意味】覇権。 Hegemony = the predominant influence or authority of one actor over others. 'Hegemonic stability theory' holds that a hegemon underwrites the system." },
    { question: "What does 'multipolarity' describe in international structure?", options: ["A system with two dominant powers in opposition, as during the Cold War", "A system dominated by a single hegemonic power under normal conditions", "A system in which several major powers each hold significant influence", "A system without any state actors of significant power in conventional usage"], answer: 2, ex: "【意味】多極性。 Multipolarity = distribution of power among multiple major actors. Contrast: unipolarity (one), bipolarity (two). Debate continues whether the current system is multipolar." },
    { question: "What does 'revisionist' mean of a state's foreign policy posture?", options: ["Adhering strictly to existing international rules and institutions", "Withdrawing from international engagement under normal conditions", "Seeking gradual reform through established institutional channels in standard practice", "Seeking to change the existing international order to its advantage"], answer: 3, ex: "【意味】（現状）変更を求める・修正主義の。 Revisionist = a state seeking to alter the current international order, often by challenging established rules, borders, or institutions. Contrast: status quo powers." },
    { question: "What does 'status quo' refer to in policy debate?", options: ["The existing state of affairs at a particular point in time", "A previously rejected proposal reintroduced for further consideration", "A future projected outcome under unchanged conditions in standard usage", "An outdated framework awaiting comprehensive reform under normal practice"], answer: 0, ex: "【意味】現状。 Status quo = the existing situation. 'Status quo ante bellum' = the situation before the war (a common peace settlement basis). 'Status quo powers' = states content with current order." },
    { question: "What does 'fait accompli' mean in strategic context?", options: ["A formal proposal still under negotiation between parties under normal conditions", "An accomplished fact, presented to others as irreversible", "A draft agreement awaiting final signature in conventional diplomatic practice", "An unresolved dispute referred to arbitration under standard international procedure"], answer: 1, ex: "【意味】既成事実。 Fait accompli = something already done, presented to others as something that cannot be undone. Crimea 2014 is the textbook contemporary example." },
    { question: "What does 'precarious' mean?", options: ["Firmly established and resistant to disruption under normal conditions", "Officially endorsed at the highest level in standard institutional practice", "Uncertain, unstable, and prone to sudden collapse", "Carefully constructed to anticipate foreseeable risks under conventional usage"], answer: 2, ex: "【意味】不安定な・危うい。 Precarious = unstable, dependent on chance, liable to collapse. 'A precarious ceasefire' = one that could break down at any moment." },
    { question: "What does 'capitulate' mean?", options: ["To negotiate from a position of equal strength under normal conditions", "To reaffirm an existing position under pressure in standard diplomatic practice", "To delay a final decision pending further consultation in conventional usage", "To surrender or yield to demands, often after resistance"], answer: 3, ex: "【意味】屈する・降伏する。 Capitulate = to surrender, especially after resistance, or to yield on a contested point. 'Refuse to capitulate to coercion' is standard policy phrasing." },
    { question: "What does 'zero-sum' mean in strategic terms?", options: ["A situation where one party's gain equals another's loss", "A situation where all parties benefit from cooperation under normal practice", "A neutral outcome in which neither party gains nor loses ground", "A long-term arrangement balancing competing interests in standard policy usage"], answer: 0, ex: "【意味】ゼロサム。 Zero-sum = a situation where gains for one party come entirely at another's expense. Contrast: 'positive-sum' (mutual gain), 'negative-sum' (mutual loss)." },
    { question: "What does 'normative' mean in policy or legal discourse?", options: ["Describing how things actually are in observed practice", "Concerning what ought to be, prescribing standards or values", "Drawing exclusively on empirical data and quantitative analysis", "Referring to procedures laid down in formal regulation"], answer: 1, ex: "【意味】規範的な。 Normative = prescribing what should be (vs descriptive — what is). 'Normative framework' = the rules and values that ought to govern. Common in international law/IR theory." }
  ],
};
